export function createController(client){
  let current={query:null,items:[],total:0,pending:false,error:null,selectedIds:[]};
  let navigation=[],undoHistory=[],retryOperation=null,activeSearch=null;
  const seen=new Map();
  const clone=value=>structuredClone(value);
  const remember=items=>{for(const row of items)seen.set(row.id,clone(row));};
  const replace=row=>{seen.set(row.id,clone(row));current.items=current.items.map(item=>item.id===row.id?clone(row):item);};
  const validate=q=>{if(!q||typeof q.filter!=='string'||!Number.isInteger(q.page)||q.page<1||!Number.isInteger(q.pageSize)||q.pageSize<1||!['name-asc','value-desc'].includes(q.sort))throw Error('Invalid query');};
  async function search(q,saveNavigation=true){
    validate(q);if(saveNavigation&&current.query)navigation.push(clone(current.query));
    const ticket={};activeSearch=ticket;current.query=clone(q);current.pending=true;current.error=null;
    try{const response=await client.search(clone(q));
      remember(response.items);current.items=clone(response.items);current.total=response.total;
    }catch(error){if(activeSearch===ticket)current.error=String(error);throw error;
    }finally{if(activeSearch===ticket)current.pending=false;}
  }
  async function update(id,patch,saveUndo=true){
    if(!seen.has(id)){
      const response=await client.search({filter:'',page:1,pageSize:Number.MAX_SAFE_INTEGER,sort:'name-asc'});remember(response.items);
    }
    const previous=seen.get(id);if(!previous)throw Error('Unknown record');
    const before=clone(previous);activeSearch={};current.pending=false;current.error=null;
    replace({...before,...clone(patch)});
    try{
      const committed=await client.update(id,clone(patch));replace(committed);
      if(saveUndo)undoHistory.push({id,before,after:clone(committed)});retryOperation=null;
    }catch(error){replace(before);current.error=String(error);retryOperation={id,patch:clone(patch)};throw error;}
  }
  return{
    search:q=>search(q),
    state:()=>clone(current),
    select(id){if(!current.selectedIds.includes(id))current.selectedIds.push(id);},
    async back(){if(navigation.length)await search(navigation.pop(),false);},
    async update(id,patch){await update(id,patch);},
    async retry(){if(!retryOperation)throw Error('No failed operation');const op=clone(retryOperation);await update(op.id,op.patch);},
    async undo(){const op=undoHistory.at(-1);if(!op)return false;await update(op.id,op.before,false);undoHistory.pop();return true;},
    exportJson(){return JSON.stringify({version:1,current,navigation,undoHistory,seen:[...seen],retryOperation});},
    restoreJson(text){const data=JSON.parse(text);if(data.version!==1||!data.current||!Array.isArray(data.navigation)||!Array.isArray(data.undoHistory)||!Array.isArray(data.seen))throw Error('Invalid controller snapshot');current=clone(data.current);current.pending=false;navigation=clone(data.navigation);undoHistory=clone(data.undoHistory);retryOperation=clone(data.retryOperation);seen.clear();for(const[id,row]of data.seen)seen.set(id,clone(row));activeSearch={};},
  };
}
